/**
 * Returns the fully hydrated page HTML with the photographer's
 * logo, brand name, hero photos, about story, services, booking,
 * spotlight, and contact details dynamically injected from siteConfig.
 */
export function getRenderedPage(config: SiteConfig = siteConfig): string {
  let html = baseHtml;

  // 1. Brand Logo: Replace in Loader, Navbar, Hero, and Footer
  if (config.brand?.logo) {
    html = html.replace(
      /src="https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6710de6ba302410a46032a1a_wedlock_logo\.png"/g,
      `src="${config.brand.logo}"`
    );
    html = html.replace(
      /srcset="https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6710de6ba302410a46032a1a_wedlock_logo[^"]*"/g,
      ""
    );
  }

  // 2. Hero Background Image (Scroll Zoom Animation) & Top-Center Brand Overlay
  if (config.hero?.image) {
    html = html.replace(/\/images\/carasol_image\.jpg/g, config.hero.image);
  }
  const heroBrandTitle = config.brand?.name || "AARQ BELLE";
  html = html.replace(
    /(<div class="header_background-image">[\s\S]*?<\/div>)(\s*<\/div>\s*<div class="header_ix-trigger")/,
    `$1
					<div class="hero-top-scrim" style="position: absolute; inset: 0 0 auto 0; height: 42%; background: linear-gradient(to bottom, rgba(0, 0, 0, 0.55) 0%, rgba(0, 0, 0, 0.18) 60%, rgba(0, 0, 0, 0) 100%); z-index: 1; pointer-events: none;"></div>
					<div class="hero-brand-overlay" style="position: absolute; top: clamp(5.25rem, 10vh, 7.25rem); left: 50%; transform: translateX(-50%); z-index: 2; width: 100%; max-width: 92vw; text-align: center; pointer-events: none; padding: 0 1rem;">
						<h1 class="hero-brand-title" style="font-family: 'Didot', Georgia, serif; font-size: clamp(2.1rem, 5vw, 4.5rem); font-weight: 400; letter-spacing: 0.16em; line-height: 1.08; color: #ffffff; text-transform: uppercase; margin: 0; text-shadow: 0 4px 24px rgba(0, 0, 0, 0.55);">${heroBrandTitle}</h1>
						<div class="hero-brand-subtitle" style="font-family: 'Qvq 0', cursive, serif; font-size: clamp(1.35rem, 2.7vw, 2.4rem); font-weight: 400; letter-spacing: 0.03em; line-height: 1.25; color: rgba(255, 255, 255, 0.94); text-transform: none; margin-top: 0.3rem; text-shadow: 0 2px 16px rgba(0, 0, 0, 0.6);">Elegance of love unveiled</div>
					</div>$2`
  );

  // 3. Hero Headline & Subtitle
  if (config.hero?.title) {
    const headline = config.hero.subtitle
      ? `${config.hero.title} ${config.hero.subtitle}`
      : config.hero.title;
    html = html.replace(
      /World-Class Wedding Photography, Wherever Love Takes You/g,
      headline
    );
  }

  // 4. Hero CTA Text & Link
  if (config.hero?.ctaText) {
    html = html.replace(
      /<div class="button-t"[^>]*>Reserve Now<\/div>/g,
      `<div class="button-t">${config.hero.ctaText}<\/div>`
    );
  }
  if (config.hero?.ctaLink) {
    html = html.replace(/href="\/reserve-now"/g, `href="${config.hero.ctaLink}"`);
  }

  // 5. About / Intro Story
  if (config.about?.title) {
    html = html.replace(
      /Crafting Timeless Wedding Stories Across the Globe/g,
      config.about.title
    );
  }
  if (config.about?.description) {
    html = html.replace(
      /(?:Wedlock International|[A-Za-zs]+) specializes in capturing the elegance and emotion of your wedding[sS]*?personal touch./g,
      config.about.description
    );
  }

  // 6. Services: Images (All 4 Services)
  if (config.services?.[0]?.image) {
    html = html.replace(
      /https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827124f12b478521c921c73_wi_weddings_img\.avif/g,
      config.services[0].image
    );
    html = html.replace(
      /srcset="https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827124f12b478521c921c73_wi_weddings_img[^"]*"/g,
      ""
    );
  }
  if (config.services?.[1]?.image) {
    html = html.replace(
      /https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827124f0b275cc3e9e68ff8_wi_destination_img\.avif/g,
      config.services[1].image
    );
    html = html.replace(
      /srcset="https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827124f0b275cc3e9e68ff8_wi_destination_img[^"]*"/g,
      ""
    );
  }
  if (config.services?.[2]?.image) {
    html = html.replace(
      /https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827124ffad60e146caee023_wi_international-availability_img\.avif/g,
      config.services[2].image
    );
    html = html.replace(
      /srcset="https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827124ffad60e146caee023_wi_international-availability_img[^"]*"/g,
      ""
    );
  }
  if (config.services?.[3]?.image) {
    html = html.replace(
      /https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827140bb240c88f8d4b48d6_wi_cw_img\.avif/g,
      config.services[3].image
    );
    html = html.replace(
      /\/images\/heritage\.avif/g,
      config.services[3].image
    );
    html = html.replace(
      /srcset="https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/6827140bb240c88f8d4b48d6_wi_cw_img[^"]*"/g,
      ""
    );
  }

  // 7. Spotlight Section (All 6 Portfolio Cards - Images, Names & Links)
  if (config.spotlight) {
    const defaultSpotlightNames = [
      "Mihiri &amp; Simon",
      "Anna &amp; Vladimir",
      "Celia &amp; Tom",
      "Laura &amp; Amar",
      "Helen &amp; Dilrukshan",
      "Inami &amp; Dimuth"
    ];
    const defaultSpotlightSlugs = [
      "mihiri-simon",
      "anna-vladimir",
      "celia-tom",
      "laura-amar",
      "helen-dilrukshan",
      "inami-dimuth"
    ];

    for (let i = 0; i < 6; i++) {
      const item = config.spotlight[i];
      if (item?.image) {
        html = html.replace(
          new RegExp('src="\\/images\\/spotlight_' + (i + 1) + '\\.jpg"', 'g'),
          'src="' + item.image + '"'
        );
      }
      if (item?.name && defaultSpotlightNames[i]) {
        html = html.replace(new RegExp(defaultSpotlightNames[i], 'g'), item.name);
        html = html.replace(new RegExp(defaultSpotlightNames[i].replace('&amp;', '&'), 'g'), item.name);
      }
      if (item?.slug && defaultSpotlightSlugs[i]) {
        html = html.replace(
          new RegExp('/international-portfolio/' + defaultSpotlightSlugs[i], 'g'),
          '/couple/' + item.slug
        );
      }
    }
  }

  // 8. Booking Section (Title, Description, and Slider Images)
  if (config.booking?.title) {
    html = html.replace(
      /<h2 class="u-text-h2 u-mb-main" js-line-animation="">Booking for[\s\S]*?International Clients[\s\S]*?<\/h2>/g,
      `<h2 class="u-text-h2 u-mb-main" js-line-animation="">${config.booking.title}<\/h2>`
    );
  }
  if (config.booking?.description) {
    html = html.replace(
      /<p>Bringing [\s\S]*? to your wedding is as simple as filling out a quick[\s\S]*?<\/p>/g,
      `<p>${config.booking.description}<\/p>`
    );
  }
  if (config.booking?.image || (config.booking?.images && config.booking.images.length > 0)) {
    const hasMultiple = Boolean(config.booking.images && config.booking.images.length > 0);
    const bImg0 = hasMultiple && config.booking.images ? (config.booking.images[0] || config.booking.image) : config.booking.image;
    const bImg1 = hasMultiple && config.booking.images ? (config.booking.images[1] || config.booking.image) : config.booking.image;
    const bImg2 = hasMultiple && config.booking.images ? (config.booking.images[2] || config.booking.image) : config.booking.image;
    const bImg3 = hasMultiple && config.booking.images ? (config.booking.images[3] || config.booking.image) : config.booking.image;

    if (bImg0) html = html.replace(new RegExp('src="\\/images\\/booking_1\\.jpg"', 'g'), 'src="' + bImg0 + '"');
    if (bImg1) html = html.replace(new RegExp('src="\\/images\\/booking_2\\.jpg"', 'g'), 'src="' + bImg1 + '"');
    if (bImg2) html = html.replace(new RegExp('src="\\/images\\/booking_3\\.jpg"', 'g'), 'src="' + bImg2 + '"');
    if (bImg3) html = html.replace(new RegExp('src="\\/images\\/booking_4\\.jpg"', 'g'), 'src="' + bImg3 + '"');
  }

  // 9. Brand Name & Tagline (Replace after specific sections so specific section texts aren't disrupted)
  if (config.brand?.name) {
    const fullName = config.brand.nameSecondary
      ? `${config.brand.name} ${config.brand.nameSecondary}`
      : config.brand.name;

    html = html.replace(/alt="Ceylon Wedlock Logo"/g, `alt="${fullName} Logo"`);
    html = html.replace(/Ceylon Wedlock/g, config.brand.name);
    html = html.replace(/Wedlock International/g, fullName);
  }

  // 10. CTA Banner: Image
  const ctaImage = config.ctaBanner?.image || "/images/cta_june.jpg";
  html = html.replace(
    /<div class="cta_background-image-mobile"><\/div>/g,
    `<div class="cta_background-image-mobile" style="background-image: url('${ctaImage}');"></div>`
  );
  html = html.replace(
    /<div class="cta_background-image"><\/div>/g,
    `<div class="cta_background-image" style="background-image: url('${ctaImage}');"></div>`
  );
  html = html.replace(
    /<img[^>]*class="cta_background-image[^"]*"[^>]*>/g,
    `<img alt="CTA Background" class="cta_background-image hide" src="${ctaImage}" loading="lazy" />`
  );

  // 10b. Hamburger / Nav Menu Background Image
  const menuImage = config.brand?.menuImage || "/images/cta_03y.jpg";
  html = html.replace(
    /<img[^>]*class="fs-navbar_menu-bg-image[^"]*"[^>]*>/g,
    `<img alt="" class="fs-navbar_menu-bg-image" loading="lazy" src="${menuImage}" />`
  );
  html = html.replace(
    /https:\/\/cdn\.prod\.website-files\.com\/66f2e119b79d1d70f35704ab\/68271bdc53edf88eb51fb590_cta_03y[^"'\s]*/g,
    menuImage
  );

  // 11. Contact: Phone (keep a single clean phone link in homepage footer)
  if (config.contact?.phone) {
    const cleanPhone = config.contact.phone.replace(/[\s-]/g, '');
    html = html.replace(
      /(<div class="footer_conatct-link-wrap u-mb-main"><a class="contact-link w-inline-block"[\s\S]*?<\/a>)\s*<a class="contact-link w-inline-block" href="tel:\+94[^"]*">[\s\S]*?<\/a>/,
      '$1'
    );
    html = html.replace(/href="tel:\+94[^"]*"/g, `href="tel:${cleanPhone}"`);
    html = html.replace(/\+94[\s]?77[\s]?63[\s]?111[\s]?84/g, config.contact.phone);
    html = html.replace(/\+94776311184/g, cleanPhone);
  }

  // 12. Contact: Email & Address
  if (config.contact?.email) {
    html = html.replace(/info@wedlockinternational\.com/g, config.contact.email);
  }
  if (config.contact?.address) {
    html = html.replace(
      /[A-Za-z0-9 &_-]+, Evergreen Park, Colombo 05\./g,
      config.contact.address
    );
  }

  // 13. Contact: Social Media
  if (config.contact?.instagram) {
    html = html.replace(
      /https:\/\/(www\.)?instagram\.com\/wedlock_international\/?/g,
      config.contact.instagram
    );
  }
  if (config.contact?.facebook) {
    html = html.replace(
      /https:\/\/(www\.)?facebook\.com\/people\/Wedlock-International\/?/g,
      config.contact.facebook
    );
  }

  // 14. WhatsApp link helper
  const cleanNumber = (config.contact?.whatsappNumber || config.contact?.phone || "94783114414").replace(/\D/g, "");
  const defaultMessage = config.contact?.whatsappMessage || "Hello! I would like to inquire about wedding photography availability and packages.";
  const whatsappUrl = `https://wa.me/${cleanNumber}?text=${encodeURIComponent(defaultMessage)}`;

  // 15. Navbar & Drawer Action Button -> Reserve Now (WhatsApp), plus Section CTA Links
  html = html.replace(
    /<div class="button-t_bridge">[^<]*<\/div>/g,
    `<div class="button-t_bridge">Reserve Now</div>`
  );
  html = html.replace(
    /(>Explore Now[\s\S]*?<a class="button-link w-inline-block"[^>]*?)href="[^"]*"/g,
    `$1href="/portfolio"`
  );
  html = html.replace(
    /(>Start Your Journey Here[\s\S]*?<a class="button-link w-inline-block"[^>]*?)href="[^"]*"/g,
    `$1href="${whatsappUrl}" target="_blank" rel="noopener noreferrer"`
  );
  html = html.replace(
    /(>Get in Touch[\s\S]*?<a class="button-link w-inline-block"[^>]*?)href="[^"]*"/g,
    `$1href="#footer"`
  );
  html = html.replace(
    /href="\/ceylonwedlock"/g,
    `href="${whatsappUrl}" target="_blank" rel="noopener noreferrer"`
  );

  // 16. Navbar Links: Remove Tours & Desktop Reserve Now text, Link Contact to Footer, Remove FAQ from drawer, Ensure Reviews link is present
  html = html.replace(/<a[^>]*href="\/tours"[^>]*>[\s\S]*?<\/a>/gi, '');
  html = html.replace(/<a[^>]*href="\/faq"[^>]*>[\s\S]*?<\/a>/gi, '');
  html = html.replace(/<a class="nav-link_item[^"]*"[^>]*>(?:(?!<\/a>)[\s\S])*?>Reserve Now<[\s\S]*?<\/a>/gi, '');
  html = html.replace(/<div class="fs-navbar_link-host">(?:(?!<div class="fs-navbar_link-host">)[\s\S])*?href="\/insights"[\s\S]*?<\/a><\/div>\s*<\/div>/gi, '');
  html = html.replace(
    /<a class="fs-menu-link[^"]*"[^>]*href="(?:\/reserve-now|#booking)"[^>]*>/gi,
    `<a class="fs-menu-link w-inline-block" href="${whatsappUrl}" target="_blank" rel="noopener noreferrer">`
  );
  html = html.replace(/href="\/contact"/g, 'href="#footer"');

  // Insert Reviews link in desktop nav if not already present
  if (!html.includes('href="/reviews" class="nav-link_item') && !html.includes('class="nav-link_item" href="/reviews"')) {
    html = html.replace(
      /(<a class="nav-link_item[^"]*"[^>]*href="\/portfolio">[\s\S]*?<\/a>)/,
      `$1<a class="nav-link_item w-inline-block" data-w-id="2575dde9-084a-934d-4dc8-e6c38ca5d10f" href="/reviews"><div class="u-text-main">Reviews</div><div class="nav-link_underline"></div></a>`
    );
  }

  // 17. Remove YouTube Icon Everywhere
  html = html.replace(/<a[^>]*class="footer_social-link[^"]*"[^>]*>[\s\S]*?M20\.5686 4\.77345[\s\S]*?<\/a>/gi, '');
  html = html.replace(/<a[^>]*href="https:\/\/www\.youtube\.com[^"]*"[^>]*>[\s\S]*?<\/a>/gi, '');

  // 18. Footer Cleanups: Add id="footer", Clean Quick Links & Inquiries menu, Tagline & Copyright
  html = html.replace(/<footer class="footer_component" data-theme="dark">/g, '<footer id="footer" class="footer_component" data-theme="dark">');

  const cleanFooterMenu = `<div class="w-layout-grid footer_menu-wrapper">
\t\t\t\t\t<div class="footer_link-list">
\t\t\t\t\t\t<h3 class="u-text-h5">Quick Links</h3>
\t\t\t\t\t\t<a class="footer_link w-inline-block w--current" href="/"><div>Home</div><div class="footer_link-underline"></div></a>
\t\t\t\t\t\t<a class="footer_link w-inline-block" href="/about-us"><div>About Us</div><div class="footer_link-underline"></div></a>
\t\t\t\t\t\t<a class="footer_link w-inline-block" href="/portfolio"><div>Portfolio</div><div class="footer_link-underline"></div></a>
\t\t\t\t\t\t<a class="footer_link w-inline-block" href="/reviews"><div>Reviews</div><div class="footer_link-underline"></div></a>
\t\t\t\t\t</div>
\t\t\t\t\t<div class="footer_link-list">
\t\t\t\t\t\t<h3 class="u-text-h5">Inquiries</h3>
\t\t\t\t\t\t<a class="footer_link w-inline-block" href="#footer"><div>Contact</div><div class="footer_link-underline"></div></a>
\t\t\t\t\t\t<a class="footer_link w-inline-block" href="${whatsappUrl}" target="_blank" rel="noopener noreferrer"><div>Reserve Now</div><div class="footer_link-underline"></div></a>
\t\t\t\t\t</div>
\t\t\t\t</div>`;

  html = html.replace(
    /<div class="w-layout-grid footer_menu-wrapper">[\s\S]*?<\/div>\s*<\/div>\s*<div class="footer_bottom-wrapper">/,
    `${cleanFooterMenu}\r\n\t\t\t</div>\r\n\t\t\t<div class="footer_bottom-wrapper">`
  );

  html = html.replace(
    /<div class="footer_site-credit">[\s\S]*?<\/div>\s*<\/div>/,
    `<div class="footer_site-credit"><div class="footer_credit-text">${config.brand?.tagline || ""}</div></div>`
  );

  const currentYear = new Date().getFullYear();
  html = html.replace(
    /<div class="footer_credit-text" data-current-year="">[^<]*<\/div>\s*<div class="footer_credit-text">[^<]*<\/div>/g,
    `<div class="footer_credit-text"> ${currentYear} ${config.brand?.name || "Wedlock International"}. All rights reserved.</div>`
  );

  // 19. Smooth scroll to top when clicking Home link on the homepage
  html += `\n<script>
document.addEventListener('click', function(e) {
  var a = e.target.closest('a');
  if (a && a.getAttribute('href') === '/' && window.location.pathname === '/') {
    e.preventDefault();
    var menuBtn = document.querySelector('.fs-navbar_menu-button');
    var menu = document.querySelector('.fs-navbar_menu');
    if (menu && menu.classList.contains('w--open') && menuBtn) {
      menuBtn.click();
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
});
</script>`;

  return html;
}

export const pageContent: string = getRenderedPage(siteConfig);
